AggOp.definition:
/** A single aggregate operation. `count` is the only op that needs no measure
 *  column (it counts rows); the rest reduce one column's values. The server-side
 *  matrix (backends/go aggOpAllowed + the TS AGG_OPS_BY_TYPE) decides which ops a
 *  field's type permits. */
type AggOp = "count" | "count_distinct" | "sum" | "avg" | "min" | "max";

AggregationClause.definition:
/** One optional "metric" pinned above the table: a single aggregate over a single
 *  measure column, optionally broken down by one or more group columns.
 *
 *  Scope is deliberately the *whole filtered set* — the same WHERE as the table,
 *  but NOT its ORDER BY / LIMIT / OFFSET. It is always evaluated on the server
 *  (a real GROUP BY), so it reflects every matching row, not just the visible
 *  page. Lives inside QueryState so it round-trips through `?q=`, saved queries,
 *  and undo/redo for free — a saved query is a saved dashboard. */
interface AggregationClause {
    dateGrouping?: MetricDateGrouping;
    expression?: string;
    expressionY?: string;
    scope?: MetricScope;
    sort?: MetricSort[];
    groupLimit?: number;
    display?: MetricDisplay;
    layout?: MetricLayout;
    distribution?: MetricDistribution;
    diagnostics?: string[];
    /** Preserved source operation when this client does not implement it. */
    unsupportedOp?: string;
    /** Stable id; keys the metric panel and survives a `?q=` round-trip. */
    id: string;
    op: AggOp;
    /** Measure column (FieldDef.name). Omit only for `count` (⇒ COUNT(*)). */
    field?: string;
    /** Group-by columns, in axis order. `[]` = a single grand-total value.
     *  One ⇒ a list/bar breakdown; two ⇒ an x/y pivot; three+ ⇒ a flat table. */
    groupBy: string[];
    /** Panel header override; defaults to a derived label like "avg total". */
    label?: string;
    /** This metric's own row predicate (CNF, like `QueryState.where`), ANDed with
     *  the table WHERE before grouping. The table rows are unchanged. In grouped
     *  mode it refers to grouped-result fields. Shown-row metrics apply it inside
     *  the shown page. */
    where?: WhereTerm[];
    /** Drop small groups before sorting, `groupLimit` and Other. A number counts
     *  rows (after `where`); `{ min, distinct: field }` counts a field's distinct
     *  non-null values and `{ min, sum: field }` sums a numeric field, ignoring
     *  nulls. Requires at least one grouping field; `min` is an integer
     *  1–1,000,000. Removed groups are reported as `hiddenGroups`. */
    minCount?: number | MetricMinCountOf;
    /** A trailing window or running value over the calendar intervals of
     * `dateGrouping`. Computed from ordinary metrics, so every engine supports it. */
    window?: MetricWindow;
    /** Express each bucket as a fraction of a total of the same measure. */
    share?: MetricShare;
}

CalendarDisplay.definition:
type CalendarDisplay = {
    style?: "human" | "iso" | "custom";
    pattern?: string;
    /** UTC by default; an IANA timezone or local may be selected explicitly. */
    timeZone?: string;
    locale?: string;
};

CalendarGroupKey.definition:
/** A grouping key that buckets a datetime field by calendar interval: one
 * group per interval, keyed by the interval's start as an ISO instant. The
 * result column is named after the field. Intervals follow the metric
 * calendar (`dateGrouping`), including daylight-saving changes; weeks start
 * on Monday. */
interface CalendarGroupKey {
    field: string;
    interval: MetricCalendarInterval;
    /** IANA timezone identifier; omitted means UTC. */
    timeZone?: string;
}

CellDisplay.definition:
type CellDisplay = JsonCellDisplay | ({
    kind: "date" | "datetime";
    sourceUnit?: "iso" | "epochSeconds" | "epochMilliseconds";
} & CalendarDisplay) | ({
    kind: "time";
    sourceUnit?: "iso" | "epochSeconds" | "epochMilliseconds" | "secondsOfDay" | "millisecondsOfDay";
} & CalendarDisplay) | {
    kind: "duration";
    sourceUnit?: "milliseconds" | "seconds" | "minutes" | "hours" | "days";
    style?: "human" | "long" | "clock" | "custom";
    pattern?: string;
    decimals?: number;
} | {
    kind: "number" | "percent";
    decimals?: number;
    locale?: string;
} | {
    kind: "chip";
    labels?: Record<string, string>;
    tones?: Record<string, "neutral" | "success" | "warning" | "danger">;
}
/** `truncate` keeps one line with an ellipsis. `lines` (1–20) wraps the text
 * and clamps it to that many lines with an ellipsis; it takes precedence. */
 | {
    kind: "text";
    truncate?: boolean;
    lines?: number;
};

FilterOp.definition:
/** All filter operators across both source projects, unioned. Every value can
 *  be NULL, so `is_null`/`is_not_null` are valid for every field type. */
type FilterOp = "=" | "!=" | ">" | ">=" | "<" | "<=" | "contains" | "starts_with" | "ends_with" | "matches_regex" | "not_matches_regex" | "length_gt" | "length_lt" | "length_eq" | "includes" | "is_null" | "is_not_null";

GroupingDefinition.definition:
/** One grouping stage over the complete source population. QueryState.where is
 * HAVING in this mode; source.where is the pre-group WHERE. The source snapshot
 * also restores the record layout, paging, metrics and item details on exit. */
interface GroupingDefinition {
    /** Field names, or calendar keys (`{ field, interval, timeZone }`) that
     * group a datetime field by interval. Each field appears once; its result
     * column is named after the field. */
    keys: GroupKey[];
    summaries: SummaryColumn[];
    representative: RepresentativeRow | null;
    diagnostics?: string[];
}

GroupingState.definition:
interface GroupingState extends GroupingDefinition {
    source: QueryState;
}

HostQueryState.definition:
/**
 * Query state a host owns and registers with `useQueryTable({ hostQuery })`,
 * such as a keyword clause it runs itself. It travels with the table query
 * through saves, links, history and resets as one definition. `params` are
 * named lists of strings, like URL search parameters; the host's own
 * `normalize` interprets them. Version 0 marks a payload that could not be
 * read, and is always rejected on restore.
 */
interface HostQueryState {
    version: number;
    params: Record<string, string[]>;
}

ItemDetailsState.definition:
interface ItemDetailsState {
    modes: ItemDetailMode[];
    /** A self-contained view travels with shared links; saved-view IDs are device-local. */
    view?: PropertyViewState;
    /** Independent layouts for each modality. Legacy view is the fallback. */
    views?: Partial<Record<ItemPropertyMode, PropertyViewState>>;
    page?: ItemPageOptions;
    active?: {
        id: RowId;
        mode: "modal" | "expand";
    };
    /** Record-specific JSON presentation; independent of property instance/layout IDs. */
    jsonInspections?: ScopedJsonInspectionState[];
}

ItemPageOptions.definition:
interface ItemPageOptions {
    /** Empty uses the current page with the item modal and query state. */
    urlTemplate: string;
    target: "_blank" | "_self";
}

JsonCellDisplay.definition:
/** Presentation hints only: field types still determine query/filter semantics. */
interface JsonCellDisplay {
    kind: "json";
    /** auto accepts objects, JSON text and repeatedly encoded/escaped JSON text.
     * value keeps a native string literal; json parses text once; escaped unwraps it. */
    encoding?: "auto" | "value" | "json" | "escaped";
    /** Maximum string-unwrapping passes, 1–8. Default 4. */
    maxDecodeDepth?: number;
    /** Inline preview length, 20–500 characters. Default 80. */
    previewLength?: number;
    /** Override initially expanded container levels, 0–8.
     * The root starts open. By default, nested containers with up to 3 entries
     * open; larger nested containers collapse. */
    expandDepth?: number;
}

JsonInspectionScope.definition:
interface JsonInspectionScope {
    dataset: string;
    rowId: RowId;
    field: string;
}

JsonInspectionState.definition:
/** Portable presentation only. Arrays are ordered sets; their order is retained. */
interface JsonInspectionState {
    version: 1;
    open: boolean;
    search: string;
    searchMode: "filter" | "find";
    raw: boolean;
    collapsedPaths: string[];
    expandedBuckets: string[];
    visibleEntryLimit: number;
    selectedMatch?: JsonMatchIdentity;
    /** Explicit expansion choices made while searching, in interaction order. */
    searchOverrides: {
        path: string;
        expanded: boolean;
    }[];
}

JsonMatchIdentity.definition:
interface JsonMatchIdentity {
    path: string;
    part: "key" | "value" | "path";
    start: number;
}

LinkDestination.definition:
/** Where a link column points. Placeholders and key filters read the group
 * row: its keys and non-link summaries. */
type LinkDestination = 
/** `{field:name}` placeholders over keys and summaries; values are
 * percent-encoded. The result must be an HTTP(S) or relative URL. */
{
    kind: "template";
    template: string;
}
/** A query composed by query-table and routed by the host's
 * `linkTargets[target](query, params)`. */
 | {
    kind: "query";
    target: string;
    /** "source" (default) starts from `grouping.source`, keeping its
     * filters, columns and order; "empty" starts from `EMPTY_QUERY`. */
    base?: "source" | "empty";
    /** Add `=`/`is_null` per group key, as `groupSourceQuery` does. Default true. */
    keyFilters?: boolean;
    /** Applied last, with `applyPatch`. */
    patch?: QueryPatch;
    /** Static parameters passed to the host target. */
    params?: Record<string, string>;
};

LinkSpec.definition:
/** A group-grain link column (`SummaryColumn` with `op: "link"`). Computed on
 * the client from the returned group row; never sent to a server. */
interface LinkSpec {
    /** Static text, or the value of a group key or summary column. */
    label: string | {
        column: string;
    };
    to: LinkDestination;
}

MetricAxisScale.definition:
/** Bounds use raw result units; omitted bounds are inferred from the data. */
interface MetricAxisScale {
    mode?: "linear" | "log";
    min?: number;
    max?: number;
}

MetricCalendarInterval.definition:
/** Calendar intervals: each bucket is one interval on the timeline, keyed by
 * its start as an ISO instant. */
type MetricCalendarInterval = "hour" | "day" | "week" | "month" | "year";

MetricCycleInterval.definition:
/** Cyclic intervals: each bucket is one slot of a repeating cycle, keyed by a
 * number. `hourOfDay` is the local hour, 0–23; `dayOfWeek` the ISO weekday,
 * 1 (Monday) to 7 (Sunday). */
type MetricCycleInterval = "hourOfDay" | "dayOfWeek";

MetricDateGrouping.definition:
/** Calendar grouping, currently executed over complete local populations. */
interface MetricDateGrouping {
    field: string;
    interval: MetricCalendarInterval | MetricCycleInterval;
    /** IANA timezone identifier; omitted settings retain UTC behavior. */
    timeZone?: string;
    /** Add a bucket for every interval of the range, or for every slot of a
     * cyclic interval. */
    includeEmpty: boolean;
    /** The calendar range empty intervals fill; for a cyclic interval, the range
     * whose empty occurrences count. */
    range: "query" | "observed" | "custom";
    start?: string;
    end?: string;
    /** "exclude" leaves out intervals the query's bounds cut, and intervals that
     * have not ended by the evaluation time; omitted includes them. A cyclic
     * interval's intervals are its hours or days. */
    partialIntervals?: "include" | "exclude";
    /** Cyclic intervals only: each slot's value is the mean of its
     * per-occurrence values, and a box distribution summarises them. Only whole
     * occurrences count. Computed from a calendar metric by planMetricSeries. */
    occurrence?: MetricDateOccurrence;
}

MetricDateOccurrence.definition:
/** Summarise each cyclic slot over its occurrences: every whole day or hour
 * the slot covers inside the query's time bounds. */
interface MetricDateOccurrence {
    /** One occurrence: "day" (dayOfWeek only) or "hour". */
    interval: "hour" | "day";
    /** Count occurrences without rows: 0 for direct COUNT, COUNT_DISTINCT and
     * SUM metrics, no value for other expressions. false leaves them out. */
    includeEmpty: boolean;
}

MetricDisplay.definition:
interface MetricDisplay {
    kind: "auto" | "value" | "table" | "list" | "bar-horizontal" | "bar-vertical" | "line" | "pie" | "donut" | "scatter" | "box" | "histogram";
    valueLabel?: string;
    xLabel?: string;
    yLabel?: string;
    format?: MetricValueFormat;
    xFormat?: MetricValueFormat;
    yFormat?: MetricValueFormat;
    legendPosition?: "left" | "right" | "top" | "bottom" | "none";
    /** Maximum displayed groups; does not change the computed result or ordering. */
    maxGroups?: number;
    /** Show the exact additive remainder in pie/donut (default true) or list (default false). */
    showOther?: boolean;
    list?: {
        showBars?: boolean;
        useGroupColors?: boolean;
        showValues?: boolean;
        /** Place the line bar beside the label (default) or underneath a wrapping label. */
        barPosition?: "inline" | "below";
        /** Maximum wrapped label lines for below bars (positive integer); omitted means unlimited. */
        maxLabelLines?: number;
    };
    pivot?: {
        swap?: boolean;
        rowDir?: "asc" | "desc";
        columnDir?: "asc" | "desc";
    };
    boxMean?: boolean;
    xScale?: MetricAxisScale;
    yScale?: MetricAxisScale;
}

MetricDistribution.definition:
interface MetricDistribution {
    kind: "box" | "histogram";
    input: string;
    whiskers?: "minmax" | "tukey";
    bins?: number;
}

MetricLayout.definition:
interface MetricLayout {
    widthRem: number;
    heightRem: number;
    minWidthRem: number;
    minHeightRem: number;
}

MetricMinCountOf.definition:
/** A per-group minimum measured over something other than rows: the distinct
 *  non-null values of one field (like COUNT_DISTINCT), or the sum of one
 *  numeric field (like SUM; nulls add nothing). Exactly one of `distinct` and
 *  `sum` is set. A group whose measure is an error is kept. */
type MetricMinCountOf = {
    min: number;
    distinct: string;
    sum?: never;
} | {
    min: number;
    sum: string;
    distinct?: never;
};

MetricShare.definition:
/** Divide each bucket by the total of all groups ("total") or of its first
 * grouping key ("group0"), such as one calendar interval. */
type MetricShare = "total" | "group0";

MetricValueFormat.definition:
interface MetricValueFormat {
    kind: "number" | "percent" | "duration" | "date" | "time" | "datetime";
    decimals?: number;
    sourceUnit?: "milliseconds" | "seconds" | "minutes" | "hours" | "days" | "iso" | "epochSeconds" | "epochMilliseconds" | "secondsOfDay" | "millisecondsOfDay";
    style?: "human" | "long" | "clock" | "custom" | "iso";
    pattern?: string;
    timeZone?: string;
}

MetricWindow.definition:
/** A trailing window over a calendar metric's intervals. */
interface MetricWindow {
    /** Intervals per point, its own included (2–1,000), or "all" for a running
     * value from the first interval. */
    periods: number | "all";
    /** "total" (default) evaluates the metric over every row in the window, so
     * ratios pool their parts. "mean" averages the per-interval values of a
     * single SUM, COUNT or COUNT_DISTINCT. */
    reduce?: "total" | "mean";
    /** Points whose window starts before the first interval have no value
     * ("omit", default) or use the intervals available ("include"). */
    partial?: "omit" | "include";
}

OrderByClause.definition:
/** One ORDER BY term. Array order in `QueryState.orderBy` is the sort priority. */
interface OrderByClause {
    field: string;
    dir: "asc" | "desc";
    /** NULL placement. Omitted = "last" (the historical default both projects used,
     *  preserved so old `?q=` links round-trip identically). */
    nulls?: "first" | "last";
    /** Sort by the first capture group of a regex match (or by the whole match
     *  when the pattern has no capture group). A non-match produces NULL. Regex
     *  syntax is interpreted by the executor (JavaScript locally, PostgreSQL on
     *  the bundled Go backend), so portable patterns should use their common
     *  syntax subset. */
    extract?: {
        regex: string;
    };
}

OrGroup.definition:
/** A disjunction of predicates — the inner OR of conjunctive normal form. Every
 *  member is a plain literal. See `OrOfAndsGroup` for an OR whose members may
 *  themselves be conjunctions. */
interface OrGroup {
    any: WhereClause[];
    setFilter?: SetFilterMetadata;
}

OrOfAndsGroup.definition:
/** A disjunction of conjunctions — `(a AND b) OR (c AND d)` — written
 *  `{ any: [{ all: [a, b] }, { all: [c, d] }] }`. A branch may also be a bare
 *  literal. It selects the union of its branches' rows, such as a legend
 *  selection of several (provider, model) pairs, without the exponential
 *  AND-of-ORs rewrite. Normalization keeps the shape canonical: a one-literal
 *  conjunction becomes that literal, a group whose branches are all literals is
 *  an `OrGroup`, and a single conjunction becomes top-level literals. Every
 *  literal counts against `MAX_WHERE_CLAUSES`, which therefore also bounds the
 *  number of branches. Each literal keeps its own null-exclusive negation; the
 *  group itself is never negated. */
interface OrOfAndsGroup {
    any: WhereBranch[];
    setFilter?: SetFilterMetadata;
}

PropertyFormat.definition:
/** Formats change presentation only; values retain their original types/units. */
type PropertyFormat = MetricValueFormat | {
    kind: "text" | "code" | "boolean" | "chips";
} | JsonCellDisplay | Extract<CellDisplay, {
    kind: "chip";
}> | {
    kind: "relative";
    sourceUnit?: "iso" | "epochSeconds" | "epochMilliseconds";
} | {
    kind: "currency";
    currency: string;
    decimals?: number;
};

PropertySelection.definition:
interface PropertySelection {
    /** Instance identity allows the same field to appear with different formats. */
    id: string;
    field: string;
    label?: string;
    render?: string;
    format?: PropertyFormat;
}

PropertyViewState.definition:
/** Independent of object identity and collection QueryState. [] shows no fields. */
interface PropertyViewState {
    version: 1;
    properties: PropertySelection[];
    /** Property label column width as a percentage, shared with the saved view. */
    labelWidth?: number;
}

QueryPatch.definition:
interface QueryPatch {
    /** Host identity for the patch; not interpreted. */
    id: string;
    /** Facets this patch controls. Facets not listed are never touched. */
    owns: QueryFacet[];
    /** Values for the owned facets. A `grouping` value makes this a group-stage
     *  patch: its `where` is HAVING and its filters are `grouping.source.where`. */
    query: Partial<QueryState>;
}

QueryState.definition:
interface QueryState {
    /** Host-owned state registered through `useQueryTable({ hostQuery })`.
     * Only the top-level query carries it; a grouping source never does. */
    hostState?: HostQueryState;
    /** Optional row-producing stage. `grouping.source` is the original record
     * query (its WHERE runs first). This query selects/filters/sorts the groups;
     * its `where` therefore represents HAVING. Only one stage is supported. */
    grouping?: GroupingState;
    itemDetails?: ItemDetailsState;
    /** Ordered SELECT list + per-column widths. Empty = the schema's default columns. */
    select: SelectColumn[];
    /** Refit columns to each viewer's table viewport after loading. Manual width
     *  changes clear this view preference; omitted/false uses stored widths. */
    fitToScreen?: boolean;
    /** WHERE in conjunctive normal form: the AND of these terms, each a single
     *  predicate or an OR group. A flat list of literals (no groups) is the common
     *  case and the legacy shape, decoded unchanged. */
    where: WhereTerm[];
    /** Multi-sort terms in priority order. Empty = the schema's default sort. */
    orderBy: OrderByClause[];
    /** Page size. */
    limit: number;
    /** Page offset (rows). */
    offset: number;
    /** Optional aggregate metrics shown above the table. Omitted/empty = none.
     *  Each runs as its own server GROUP BY over the WHERE-filtered set (no paging). */
    aggregations?: AggregationClause[];
}

RepresentativeOrder.definition:
interface RepresentativeOrder {
    field: string;
    dir: "asc" | "desc";
    nulls: "first" | "last";
}

ScopedJsonInspectionState.definition:
interface ScopedJsonInspectionState extends JsonInspectionScope {
    state: JsonInspectionState;
}

SelectColumn.definition:
/** One column in the SELECT list, plus the view state that travels with it.
 *  Order in `QueryState.select` is the left-to-right display order. */
interface SelectColumn {
    field: string;
    /** Pixel width override. Omitted = FieldDef.select.width, else the type default. */
    width?: number;
    /** Table-cell presentation for this column in this layout, e.g.
     *  `{ kind: "text", lines: 3 }`. Takes precedence over the field's `render`
     *  and `display`; other surfaces (details, menus, metrics) keep the field's. */
    display?: CellDisplay;
}

SetFilterMetadata.definition:
/** Presentation-only identity; execution always uses the accompanying predicates. */
interface SetFilterMetadata {
    id: string;
    mode: SetFilterMode;
    values: string[];
}

SummaryColumn.definition:
interface SummaryColumn {
    id: string;
    op: SummaryOp;
    field?: string;
    expression?: string;
    label?: string;
    /** Cell format for this output column (for example `{ kind: "percent" }` for
     * a weighted rate). Replaces any render/display inherited from the source
     * field; metrics measuring the column default their value format from it. */
    display?: CellDisplay;
    /** Required for `op: "link"`; ignored otherwise. */
    link?: LinkSpec;
}

WhereClause.definition:
/** A single filter predicate (a "literal" in CNF terms). `value` is always the
 *  raw string the UI captured; coercion to number/bool/date happens at
 *  apply/compile time based on the field's declared type (never on the value's
 *  runtime shape). Datetime comparisons also accept signed duration offsets
 *  such as "-1h" or "+8d2h10m", resolved relative to execution time.
 *  Unused for the nullary ops (`is_null`/`is_not_null`).
 *
 *  `negated` wraps the predicate in a logical NOT. It is only ever set for ops
 *  that have no complementary operator (`contains`/`starts_with`/`ends_with`/
 *  `includes`); ops with a complement negate by flipping the op itself (`>=`→`<`,
 *  `=`→`!=`, `is_null`→`is_not_null`, `matches_regex`→`not_matches_regex`) — see
 *  `negateClause` in ops.ts. NOT is null-exclusive: a NULL/empty value satisfies
 *  neither the predicate nor its negation, matching `not_matches_regex`. */
interface WhereClause {
    field: string;
    op: FilterOp;
    value: string;
    negated?: boolean;
    setFilter?: SetFilterMetadata;
}

WhereConjunction.definition:
/** One branch of an `OrOfAndsGroup` that ANDs several literals. Members are
 *  always plain literals: nesting stops at `any` → `all` → clause. */
interface WhereConjunction {
    all: WhereClause[];
}

WhereTerm.definition:
/** One conjunct of the WHERE clause: a single predicate, an OR group, or an OR
 *  of conjunctions. `QueryState.where` is the AND of these terms —
 *  `(a) AND (b OR c) AND ((d AND e) OR f)`. A bare literal is equivalent to a
 *  one-element OR group; normalization flattens singleton groups back to a
 *  literal so equality/encoding stay canonical. */
type WhereTerm = WhereClause | OrGroup | OrOfAndsGroup;
